<?php
namespace App\Jobs;use App\Models\Examination;use App\Models\User;use App\Services\Viva\VivaAuditService;use App\Services\Viva\VivaBoardValidationService;use App\Support\Examinations\ExaminationConnectionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;
final class ValidateVivaBoardImport implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int$tries=1;public int$timeout=0;public function __construct(public int$examinationId,public int$batchId,public int$actorId){$this->onQueue((string)config('viva.queue','imports'));}public function handle(ExaminationConnectionManager$c,VivaBoardValidationService$s,VivaAuditService$a):void{$c->configure(Examination::findOrFail($this->examinationId));try{$b=$s->validate($this->batchId);$a->record('VIVA_BOARD_VALIDATED',User::findOrFail($this->actorId),'staged','validated',summary:['valid'=>(int)$b->valid_rows,'warning'=>(int)$b->warning_rows,'invalid'=>(int)$b->invalid_rows],batchId:$b->id);}finally{$c->disconnect();}}}
